customCss:
/* Sequoia: black brushed aluminum, dark wood, giant sequoia bark and needles */
.preview h1, .preview h2 { letter-spacing: -0.01em; }
.preview h3, .preview h4 { letter-spacing: -0.005em; }
.preview blockquote { border-left-width: 4px; font-style: italic; }
.preview pre, .preview .code-block { border: 1px solid var(--md-border); }
.preview :not(pre) > code { border: 1px solid var(--md-border); }
.preview th { background: var(--md-code-bg); }
.preview hr { height: 2px; border-top-width: 2px; opacity: 0.8; }
